<span class="line"><span style="color:#24292E;">Copper.</span><span style="color:#6F42C1;">setPanEnabled</span><span style="color:#24292E;">(scene.controls, </span><span style="color:#005CC5;">false</span><span style="color:#24292E;">);</span></span>
